from collections import Counter

def min_cover(s: str, need: str) -> str:
    owed = Counter(need)
    missing = len(need)
    left, start, size = 0, 0, len(s) + 1
    for right, ch in enumerate(s):
        if owed[ch] > 0:
            missing -= 1
        owed[ch] -= 1
        while missing == 0:
            if right - left + 1 < size:
                start, size = left, right - left + 1
            owed[s[left]] += 1
            if owed[s[left]] > 0:
                missing += 1
            left += 1
    return s[start:start + size] if size <= len(s) else ""

perf.naive:
from collections import Counter


def min_cover(s: str, need: str) -> str:
    best = ""
    for left in range(len(s)):
        owed = Counter(need)
        missing = len(need)
        for right in range(left, len(s)):
            if owed[s[right]] > 0:
                missing -= 1
            owed[s[right]] -= 1
            if missing == 0:
                if not best or right - left + 1 < len(best):
                    best = s[left:right + 1]
                break
    return best
